// # a popped value bound to a frame local first is lent from the frame; under
// # `Iterator[Own[T]]` the pop is handed over
// def pop_local[T](xs: list[T]) -> Iterator[T]:
//     while len(xs) > 0:
//         y = xs.pop()
//         yield y  # tpyc: ok                    # -> S_RESUME_0
